export function preparedUnmappedNotes(session){return session.sources.flatMap(source=>{const match=/^note:(style|person|length|features|layers|bangs|curls|care):/.exec(source.messageId);return match?[{field:match[1],messageId:source.messageId,text:source.text,mappingStatus:'unmapped'}]:[];});}

export function parsePreparedEntryValue(field,raw){
  if(typeof raw!=='string'||raw.length>2000)fail('INVALID_ENTRY_VALUE');
  if(!raw.trim())return null;
  if(['rod_size_mm','angle_degrees','turns','time_minutes','temperature_celsius'].includes(field)){
    if(!/^(?:0|[1-9]\d*)(?:\.\d+)?$/.test(raw)||!Number.isFinite(Number(raw)))fail('EXPLICIT_NUMBER_REQUIRED');
    return Number(raw);
  }
  return raw;
}

/** Readiness only, never an access grant; server independently binds/reads both sources. */
